import { CardType, ElementAttribute, SignalOrbType } from '@zhanshuang/shared';

export interface CardVariant {
  key: string;
  star: number;
  rarity?: string;
  name: string;
  shortLabel: string;
  imageUrl: string;
  badge?: string;
  packageName?: string;
  series?: string;
}

export interface CardVariantEntry extends CardData {
  variantKey: string;
  variantStar: number;
  variantRarity?: string;
  variantName: string;
  variantBadge?: string;
  baseCardId: string;
}

export interface CardData {
  id: string;
  cardNumber: string;
  name: string;
  cardType: CardType;
  attribute: ElementAttribute;
  cost: number;
  basePP?: number;
  baseDP?: number;
  signalOrb?: SignalOrbType;
  traits: string[];
  isInstant?: boolean;
  imageUrl?: string;
  rulesText: string;
  flavorText?: string;
  series?: string;
  variants?: CardVariant[];
  packageName?: string;
  rarity?: string;
  rawCardType?: string;
  attributeName?: string;
}

